// Helper function to get quiz player data
func getQuizPlayerData(rawData json.RawMessage) (blocks.QuizPlayerData, error) {
	var playerData blocks.QuizPlayerData
	if rawData != nil {
		err := json.Unmarshal(rawData, &playerData)
		return playerData, err
	}
	return playerData, nil
}

// Helper function to check if an option is selected
func isOptionSelected(optionID string, selectedOptions []string) bool {
	for _, selected := range selectedOptions {
		if selected == optionID {
			return true
		}
	}
	return false
}

// quizVerdict says in words what became of an option, and gives the row's
// state. Only what the player picked is judged: an option left alone is not
// marked wrong, and a right one they missed is shown as the answer.
func quizVerdict(correct, picked bool) (string, string) {
	switch {
	case picked && correct:
		return "That's right", "is-ok"
	case picked:
		return "Not this one", "is-no"
	case correct:
		return "The right answer", "is-miss"
	}
	return "", ""
}

